import java.util.*;

public class Main {
    static final int[] PREFIX = {0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334};

    static boolean isLeap(long y) {
        return y % 4 == 0 && (y % 100 != 0 || y % 400 == 0);
    }

    // Days elapsed from 0001-01-01 to the given proleptic Gregorian date.
    static long ordinal(long y, int m, int d) {
        long p = y - 1;
        long total = 365 * p + p / 4 - p / 100 + p / 400 + PREFIX[m - 1];
        if (m > 2 && isLeap(y)) total++;
        return total + d - 1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long y1 = sc.nextLong();
        int m1 = sc.nextInt(), d1 = sc.nextInt();
        long y2 = sc.nextLong();
        int m2 = sc.nextInt(), d2 = sc.nextInt();
        System.out.println(ordinal(y2, m2, d2) - ordinal(y1, m1, d1));
    }
}
